$ErrorActionPreference='Stop';if($env:COMPUTERNAME -cne 'DESKTOP-O1LP5DG' -or (Get-CimInstance Win32_ComputerSystemProduct).UUID -cne 'C6440689-D11C-4C63-A463-F3722B7DDB69'){throw 'Builder mismatch'};if(@(Get-Process -Name MSBuild,dotnet,csc,vbcsc,VBCSCompiler -ErrorAction SilentlyContinue).Count){throw 'Build process active'};& shutdown.exe /s /t 0;$result=$LASTEXITCODE;Write-Output ('GuestGracefulShutdownExit='+$result);exit $result